/** 只声明这一组合实际读取的原字段；这是同一阶段状态的类型视图，不创建或冻结副本。 */
type NightDamageClaims = Pick<
  NightStageState,
  | "modifierDeaths"
  | "poisonClaims"
  | "retaliationAttacks"
  | "nightImmunities"
  | "inspectionAttacks"
  | "foxInspections"
  | "guardClaims"
  | "merchantBacklashes"
  | "blackMarketBacklashes"
  | "mechanicalEffects"
  | "awakenedEffects"
