/** 同步完成原四步组合，不改变前后记录／try-finally，也不重新打开已提交效果。 */
export function composeNightDamage(runtime: NightDamageCompositionRuntime): {
  dreamFrame: DreamNightEffects;
  damage: ReturnType<DamageResolutionSystem["resolve"]>;
