    return;
  try {
    bindRequestDeliveryGuard(
      target,
      () => demonHunterRequestScope(a.turn.night.binding.world, target) !== undefined,
      a.turn.scope,
    );
    a.turn.deadline = typeof deadline === "number" ? deadline : null;
